package steam.nova.app.features.chat.media

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Color
import android.graphics.Rect
import android.graphics.drawable.Drawable
import android.graphics.drawable.NinePatchDrawable
import android.util.Base64
import androidx.core.graphics.drawable.toDrawable
import androidx.core.graphics.get
import java.nio.ByteBuffer
import java.nio.ByteOrder

internal object SteamChatMediaPopupResources {
    private data class Images(val density: Int, val video: String, val popup: String)
    private val images = listOf(
        Images(160, "UklGRj4AAABXRUJQVlA4TDIAAAAvBUAEEIWato2g8CdWTJ3u3w5AhJCAKDb6boMTatM2YOIp7RHYSOckgItjt3XM5s0NAA==", ""),
        Images(240, "UklGRoYAAABXRUJQVlA4THoAAAAvCIAGEHWwbSRJyoR8EZAL9kXDZxIG5g/mBbAM4nquh1tRI0nR7jIKRsRIQABBBUJOf0jhtSbUtm3DeKspb6TNAgC26WgLb+XXgY6dUewkREYWmJk7CfAJMHEf+AVoqA9iAQRbRo36mtMQFIrwYxTcC4p6RBBKewTABg==", ""),
        Images(320, "UklGRowAAABXRUJQVlA4TH8AAAAvC8AIENUwbSTJ0YZ8+XyEDz8Ab+njQ4venZs0lt9Icz3cZmrb+B+TWQA5fmdHJrMSatu2YRRoSz/DjRCEEBIAQ1htUMf0nN4BG3Xka60aOIO7buJGoFC6RY1ntOwWbyR2KQF0A9Ygr+qDLRAm9BKrIRA4OjiQ5OrV+IOd/yEAAA==", ""),
        Images(480, "UklGRqAAAABXRUJQVlA4TJMAAAAvEUANEHUwqm03ChJGoQioRwSgg8NqJgldsyO/P8z1cKsJAEIyCSCBDLKZdTPK8d5TQoHbNkpyzPCLYci1AlFDl4AVOaEzvpIlJpTQMSELsfOFX0KgyldUQRZZfsNCkYdFEDc7a7GzGawkkVsZMQtIethaKAi/g/UyhHrMGLH79XCV4TrciqgA+fjoDqFn+xr+nQMA", "")
    )

    fun drawable(context: Context, popup: Boolean): Drawable {
        val resources = context.resources
        val image = images.firstOrNull { it.density >= resources.displayMetrics.densityDpi } ?: images.last()
        val bytes = Base64.decode(if (popup) image.popup else image.video, Base64.NO_WRAP)
        val bitmap = checkNotNull(BitmapFactory.decodeByteArray(bytes, 0, bytes.size)).apply { density = image.density }
        if (!popup) return bitmap.toDrawable(resources)
        fun divisions(horizontal: Boolean, opposite: Boolean): IntArray {
            val length = if (horizontal) bitmap.width else bitmap.height
            val result = arrayListOf<Int>()
            var previous = false
            for (coordinate in 1 until length - 1) {
                val pixel = if (horizontal) bitmap[coordinate, if (opposite) bitmap.height - 1 else 0]
                else bitmap[if (opposite) bitmap.width - 1 else 0, coordinate]
                val marked = Color.alpha(pixel) == 255 && Color.red(pixel) == 0
                if (marked != previous) result.add(coordinate - 1)
                previous = marked
            }
            if (previous) result.add(length - 2)
            return result.toIntArray()
        }
        val x = divisions(horizontal = true, opposite = false)
        val y = divisions(horizontal = false, opposite = false)
        val horizontalPadding = divisions(horizontal = true, opposite = true)
        val verticalPadding = divisions(horizontal = false, opposite = true)
        val padding = Rect(horizontalPadding.first(), verticalPadding.first(),
            bitmap.width - 2 - horizontalPadding.last(), bitmap.height - 2 - verticalPadding.last())
        val colors = (x.size + 1) * (y.size + 1)
        val chunk = ByteBuffer.allocate(32 + 4 * (x.size + y.size + colors)).order(ByteOrder.nativeOrder()).apply {
            put(1.toByte()); put(x.size.toByte()); put(y.size.toByte()); put(colors.toByte())
            putInt(0); putInt(0)
            putInt(padding.left); putInt(padding.right); putInt(padding.top); putInt(padding.bottom)
            putInt(0)
            x.forEach { putInt(it) }; y.forEach { putInt(it) }
            repeat(colors) { putInt(1) }
        }.array()
        val content = Bitmap.createBitmap(bitmap, 1, 1, bitmap.width - 2, bitmap.height - 2).apply { density = image.density }
        bitmap.recycle()
        return NinePatchDrawable(resources, content, chunk, padding, null)
    }
}
